import {
  IHikingPositionDTO,
  IHikingVacancyDTO,
  IHikingVacancyResponseDto,
} from '../@types/DTO/hikingPositionsAndVacancies.dto.types';
import {
  IHikingPositionFull,
  IHikingVacancy,
  IHikingVacancyResponse,
} from '../@types/hikingPositionsAndVacancies.types';

export const mapHikingPositionToFullFront = (backData: IHikingPositionDTO): IHikingPositionFull => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.description,
    desc_before: backData.desc_before,
    desc_during: backData.desc_during,
    desc_after: backData.desc_after,
  };
};

export const mapHikingVacancyToFront = (backData: IHikingVacancyDTO): IHikingVacancy => {
  return {
    id: +backData.id_vacancy,
    comment: backData.comment,
    deadline: new Date(backData.deadline),
    isActive: backData.is_active == '1',
    responsesCount: +backData.responses,
    position: {
      id: +backData.id_position,
      name: backData.name,
      description: backData.description,
    },
  };
};

export const mapHikingVacancyResponseToFront = (
  backData: IHikingVacancyResponseDto,
): IHikingVacancyResponse => {
  return {
    id: +backData.id,
    comment: backData.comment,
    id_hiking_vacancy: +backData.id_hiking_vacancy,

    date: new Date(backData.date),
    approve_user_id: +backData.approve_user_id,
    approve_date: new Date(backData.approve_date),
    user: {
      id: +backData.id_user,
      name: backData.user_name,
      surname: backData.user_surname,
      photo: backData.user_photo,
    },
  };
};
